import sys
from collections import deque

class Solution:
    def solution(self, input_str):
        lines = input_str.strip().split('\n')
        n, m = map(int, lines[0].split())
        grid = []
        for line in lines[1:]:
            grid.append(list(line))

        # Find all free cells and walls
        free_cells = set()
        for i in range(n):
            for j in range(m):
                if grid[i][j] == '.':
                    free_cells.add((i, j))

        if not free_cells:
            # No free cells, return original
            return '\n'.join(''.join(row) for row in grid) + '\n'

        # Find the bounding box of all free cells
        min_r, max_r = min(i for i, j in free_cells), max(i for i, j in free_cells)
        min_c, max_c = min(j for i, j in free_cells), max(j for i, j in free_cells)

        # Convert all cells in bounding box to free space if they're walls
        # This creates the minimal rectangle covering all free cells
        for i in range(min_r, max_r + 1):
            for j in range(min_c, max_c + 1):
                if grid[i][j] == '*':
                    grid[i][j] = '.'

        return '\n'.join(''.join(row) for row in grid) + '\n'

