    # Actual implementation with better complexity
    best = [0]
    available = list(range(total_friends))

    def dfs(idx, mask):
        nonlocal best[0]

        if idx == len(available):
            best[0] = max(best[0], mask.bit_count())
            return

        friend = available[idx]

        # Option 1: Don't include this friend
        dfs(idx + 1, mask)

        # Option 2: Include this friend (if it doesn't conflict with already in mask)
