    pref_lists = []
    for i in range(1, n + 1):
        # Remove self and sort by cost
        city_prefs = []
        for j in range(1, n + 1):
            if i != j:
                city_prefs.append((cost[i][j], j))
        city_prefs.sort()
        pref_lists.append([p[1] for p in city_prefs])  # Keep only city indices in order

    # Try to find stable matching
    partner = [0] * (n + 1)

    # Check for stability violation and try to fix it
    def check_and_propose():
        # Find any city that is happy
        for i in range(1, n + 1):
            if partner[i] == 0:
                continue

            current = partner[i]
            best_available = None

            # Find if there's a better available partner
            for p in pref_lists[i-1]:
                if p == current:
                    break
                if partner[p] == 0:  # p is available
                    best_available = p
                    break

            if best_available is not None:
                # Swap if better
                partner[i] = best_available
                partner[best_available] = i
                return True

        # Try to find two free cities
        free1 = None
        free2 = None
        for i in range(1, n + 1):
            if partner[i] == 0:
                if free1 is None:
                    free1 = i
                else:
                    free2 = i
                    break

        if free1 is not None and free2 is not None:
            partner[free1] = free2
            partner[free2] = free1
            return True

        return False

    # Check for stability - no two cities should both prefer each other
    def is_stable():
        for i in range(1, n + 1):
            if partner[i] == 0:
                return False  # Must be perfectly matched

            current = partner[i]

            for j in range(1, n + 1):
                if j == i or j == current:
                    continue
                if partner[j] == 0:
                    continue

                others = partner[j]

                # Check if (i,j) is a blocking pair
                # i prefers j over current
                i_pref = False
                for p in pref_lists[i-1]:
                    if p == current:
                        i_pref = False
                        break
                    if p == j:
                        i_pref = True
                        break
                    if p == others:
                        break

                if not i_pref:
                    continue

                # j prefers i over others
                j_pref = False
                for p in pref_lists[j-1]:
                    if p == others:
                        j_pref = False
                        break
                    if p == i:
                        j_pref = True
                        break
                    if p == current:
                        break

                if j_pref:
                    return False  # Blocking pair exists

        return True

    # Try iterations to reach stable matching
    for _ in range(1000):
        if is_stable():
            break
        if not check_and_propose():
            break

    # Final stability check
    if is_stable():
        result = []
        for i in range(1, n + 1):
            result.append(str(partner[i]))
        return '\n'.join(result) + '\n'

    return '-1\n'
