import sys

def check_axis_aligned_square(grid, r, c, size):
    """
    Check if there's a valid axis-aligned square at (r, c) with given size.
    r, c is top-left corner (0-indexed)
    """
    n, m = len(grid), len(grid[0])

    # Check all border positions are '1'
    # Top and bottom rows
    for col in range(c, c + size):
        if grid[r][col] != '1':
            return False
        if grid[r + size - 1][col] != '1':
            return False

    # Left and right columns
    for row in range(r + 1, r + size - 1):
        if grid[row][c] != '1':
            return False
        if grid[row][c + size - 1] != '1':
            return False

    # Interior must be all '0'
    for row in range(r + 1, r + size - 1):
        for col in range(c + 1, c + size - 1):
            if grid[row][col] != '0':
                return False

    # Check for foreign 1s touching the border
    for row in [r, r + size - 1]:
        for col in range(c - 1, c + size):
            if 0 <= row < n and 0 <= col < m:
                if grid[row][col] == '1' and not (r <= row <= r + size - 1 and c <= col <= c + size - 1):
                    return False

    for col in [c, c + size - 1]:
        for row in range(r - 1, r + size):
            if 0 <= row < n and 0 <= col < m:
                if grid[row][col] == '1' and not (r <= row <= r + size - 1 and c <= col <= c + size - 1):
                    return False

    return True

def check_diagonal_square(grid, center_r, center_c, size):
    """
    Check if there's a valid diagonal square (diamond) centered at (center_r, center_c) with given size.
    size is the side length (distance between parallel diagonal sides)
    """
    n, m = len(grid), len(grid[0])

    if center_r < 0 or center_r >= n or center_c < 0 or center_c >= m:
        return False

    # For a diagonal square with "size" s, we need to check the diamond shape
    # The diamond has vertices at (center_r - (s-1)//2, center_c), etc.
    # A diamond of Manhattan radius k has perimeter points where |dr| + |dc| = k

    max_radius = size

    # Check all border points of the diamond
    # Points on border satisfy: |dr| + |dc| == max_radius
    for dr in range(-max_radius, max_radius + 1):
        for dc in range(-max_radius, max_radius + 1):
            if abs(dr) + abs(dc) == max_radius:
                rr, cc = center_r + dr, center_c + dc
                if 0 <= rr < n and 0 <= cc < m:
                    if grid[rr][cc] != '1':
                        return False

    # Check interior is all '0'
    # Interior points satisfy: |dr| + |dc| < max_radius
    for dr in range(-max_radius + 1, max_radius):
        for dc in range(-max_radius + 1, max_radius):
            if abs(dr) + abs(dc) < max_radius:
                rr, cc = center_r + dr, center_c + dc
                if 0 <= rr < n and 0 <= cc < m:
                    if grid[rr][cc] != '0':
                        return False

    # Even/odd parity: diamond has integer size
    # Center must have same parity as border
    # No foreign '1's touching the border
    for rr in range(max(0, center_r - max_radius - 1), min(n, center_r + max_radius + 2)):
        for cc in range(max(0, center_c - max_radius - 1), min(m, center_c + max_radius + 2)):
            if abs(rr - center_r) + abs(cc - center_c) == max_radius:  # On border
                if grid[rr][cc] == '1':
                    continue  # Already checked
            elif abs(rr - center_r) + abs(cc - center_c) <= max_radius + 1:
                if grid[rr][cc] == '1':
                    # Touching the border
                    return False

    return True

def solution(s):
    lines = s.strip().split('\n')
    idx = 0

    if idx >= len(lines) or lines[idx] == '':
        return '0'

    t = int(lines[idx])
    idx += 1
    results = []

    for _ in range(t):
