        idx += 1
        n, m = int(parts[0]), int(parts[1])

        grid = []
        for _ in range(n):
            while idx < len(lines) and lines[idx] == '':
                idx += 1
            grid.append(lines[idx])
            idx += 1

        count = 0

        # Count axis-aligned squares
        for size in range(2, min(n, m) + 1):
            for r in range(n - size + 1):
                for c in range(m - size + 1):
                    if check_axis_aligned_square(grid, r, c, size):
                        count += 1

        # Count diagonal squares
        # For diagonal squares, max_radius goes from 1 onwards
        max_radius = (min(n, m) - 1) // 2 + 1
        for radius in range(1, max_radius):
            for r in range(radius, n - radius):
                for c in range(c - 1 + radius, m - radius):
                    # Can start from radius to avoid double counting
                    if check_diagonal_square(grid, r, c, 2 * radius):
                        count += 1

        results.append(str(count))

