    # Build abbreviation to year mapping by simulating the IAO process
    abb_to_year = {}
    used = set()
    year = 1989

    # Generate enough years to cover all possible suffixes
    # For 9-digit suffix up to "999", we may need year 2999 or more
    # Using a safe upper bound
    max_year = 1000000  # Sufficient for 9-digit suffixes in test cases
    while year <= max_year:
