        # Try to find the shortest valid suffix for this year
        for l in range(1, min(10, len(s) + 1)):
            suffix = s[-l:]
            if suffix not in used:
                used.add(suffix)
                abb_to_year[suffix] = year
                break
        year += 1

    # Process each query
    result = []
    for i in range(1, n + 1):
        if i < len(lines):
            abbr = lines[i].strip()
            if abbr.startswith("IAO'"):
                suffix = abbr[4:]  # Extract part after "IAO'"
