def solution(data: str) -> str:
    lines = data.strip().split('\n')
    idx = 0

    try:
        q = int(lines[idx].strip())
        idx += 1
    except:
        return ""

    results = []

    for _ in range(q):
        try:
            n = int(lines[idx].strip())
            idx += 1
            a = list(map(int, lines[idx].strip().split()))
            idx += 1

            if n <= 1:
                results.append(0)
                continue

            unique = sorted(list(set(a)))
            n_unique = len(unique)

            if n_unique <= 1:
                results.append(0)
                continue

            first = {}
            last = {}

            for i, x in enumerate(a):
                if x not in first:
                    first[x] = i
                last[x] = i

            chain = 1
            max_chain = 1

            for i in range(n_unique - 1):
                v1 = unique[i]
                v2 = unique[i + 1]

                if last[v1] < first[v2]:
                    chain += 1
                    max_chain = max(max_chain, chain)
                else:
                    chain = 1

            results.append(n_unique - max_chain)
        except Exception:
            break

    return '\n'.join(map(str, results))
