def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    adj = [[] for _ in range(n + 1)]
    edges = []

    for i in range(1, m + 1):
        if i < len(lines):
            u, v = map(int, lines[i].split())
            adj[u].append(v)
            edges.append((u, v))

    # Compute all-pairs shortest paths using BFS from each node
    # Since all edges have weight 1
    dist = [[float('inf')] * (n + 1) for _ in range(n + 1)]

    for start in range(1, n + 1):
        queue = [start]
        dist[start][start] = 0
        idx = 0
        while idx < len(queue):
            u = queue[idx]
            idx += 1
            for v in adj[u]:
                if dist[start][v] == float('inf'):
                    dist[start][v] = dist[start][u] + 1
                    queue.append(v)

    # Now we need to find 4 distinct cities a, b, c, d such that
    # dist[a][b] + dist[b][c] + dist[c][d] is maximized
    # We can try fixing a and d, then find optimal b and c
    # Since n <= 3000, we need O(n^2 or n^3) approach

    max_total = -1
    best_order = None

    # Fix first and last cities, find best middle two
    for a in range(1, n + 1):
        if dist[a][a] == float('inf'):
            continue
        for d in range(1, n + 1):
            if a == d:
                continue
            if dist[a][d] == float('inf'):
                continue

            total_diff = dist[a][d]
            # dist[a][b] + dist[c][d] should balance around this
            # Actually we want dist[a][b] + dist[b][c] + dist[c][d]
            # Fix a and d, we need to find b, c such that dist[a][b] + dist[b][c] + dist[c][d] is max

            for b in range(1, n + 1):
                if b == a or b == d:
                    continue
                if dist[a][b] == float('inf'):
                    continue

                for c in range(1, n + 1):
                    if c == a or c == b or c == d:
                        continue
                    if dist[b][c] == float('inf') or dist[c][d] == float('inf'):
                        continue

                    total = dist[a][b] + dist[b][c] + dist[c][d]
                    if total > max_total:
                        max_total = total
                        best_order = (a, b, c, d)

    if max_total == -1:
        return "1 2 3 4"  # fallback

    return f"{best_order[0]} {best_order[1]} {best_order[2]} {best_order[3]}"
