    result = []

    for i in range(n - m + 1):
        # Map for forward and backward tracking of pairs
        # pairs[x] = y means x maps to y
        p = {}
        valid = True

        for j in range(m):
            s_char = s[i + j]
            t_char = t[j]

            # If characters are the same, no pairing needed (could be unpaired)
            if s_char == t_char:
                continue

            # s_char should map to t_char
            if s_char in p:
                if p[s_char] != t_char:
                    valid = False
                    break
            else:
                p[s_char] = t_char

            # By symmetry, t_char should map back to s_char
            if t_char in p:
                if p[t_char] != s_char:
                    valid = False
                    break
            else:
                p[t_char] = s_char

        if valid:
            result.append(i + 1)  # 1-indexed positions

    result.sort()

    output_lines = [str(len(result))]
    if result:
        output_lines.append(' '.join(map(str, result)))
    else:
        output_lines.append('')

