import math
from collections import defaultdict
import sys

def get_prime_factors(n):
    """Get unique prime factors of n"""
    factors = set()
    d = 2
    while d * d <= n:
        if n % d == 0:
            factors.add(d)
            while n % d == 0:
                n //= d
        d += 1
    if n > 1:
        factors.add(n)
    return list(factors)

