        counts.append(int(parts[1]))

    # Use DFS with memoization to count valid codes
    # State: (position, tuple of current match counts)
    memo = {}

    def count_valid(idx, current_matches):
        state = (idx, tuple(current_matches))
        if state in memo:
            return memo[state]

        # If we've placed all bits, check if all match counts are exactly satisfied
        if idx == n:
            return 1 if all(cm == c for cm, c in zip(current_matches, counts)) else 0

        total = 0
        for bit in ['0', '1']:
            # Calculate new match counts
            new_matches = list(current_matches)
            for i in range(m):
                if bit == attempts[i][idx]:
                    new_matches[i] += 1

            # Pruning: if any attempt already exceeds its required count, skip this branch
            if any(new_matches[i] > counts[i] for i in range(m)):
                continue

            # If all attempts have already reached their required count,
            # all remaining bits must mismatch all attempts
            if all(new_matches[i] == counts[i] for i in range(m)):
                # Check if we can fill remaining positions with mismatches
                can_complete = True
                for k in range(idx, n):
                    for i in range(m):
                        if attempts[i][k] == bit:
                            can_complete = False
                            break
                if can_complete:
                    total += count_valid(idx + 1, new_matches)
            else:
                total += count_valid(idx + 1, new_matches)

        memo[state] = total
        return total

