    # Precompute Fibonacci numbers up to max_n
    fib = [1, 2]
    while fib[-1] < max_n:
        fib.append(fib[-1] + fib[-2])

    # Memoization for count_ways across all queries
    memo = {}

    # Iterative DP to avoid recursion depth issues
    def get_count(n):
        if n == 0:
            return 1
        if n in memo:
            return memo[n]

