                    for sb in range(0, 30):
                        if is_valid_set(sa, sb, idx + 1):
                            if try_solve(idx + 1, rem_a - sa, rem_b - sb):
                                return True
                            if sa * sb == 0:
                                break
                        if sb * sa == 0:
                            break
                return False
            else:  # B wins
                for sb in range(1, 35):
                    if sb < 15: continue
                    for sa in range(0, 30):
                        if is_valid_set(sa, sb, idx + 1):
                            if try_solve(idx + 1, rem_a - sa, rem_b - sb):
                                return True
                        if sa * sb == 0:
                            break
                        if sb * sa == 0:
                            break
                return False
            return False

        return try_solve(0, total_a, total_b)

def solve_one(a, b):
    for sa, sb in [(3, 0), (3, 1), (3, 2), (2, 3), (1, 3), (0, 3)]:
        if sa + sb > 5:
            continue

        # Generate all win patterns
        from itertools import combinations
        total = sa + sb

        if sa == 0:
            patterns = [[0] * total]
        elif sa == total:
            patterns = [[1] * total]
        else:
            patterns = []
            for combo in combinations(range(total), sa):
                pat = [0] * total
                for i in combo:
                    pat[i] = 1
                patterns.append(pat)

        for pat in patterns:
            # Verify win pattern works
            remaining_a, remaining_b = a, b
            ok = True
            also_this_check
            if ok:
                # Found valid pattern
                return (sa, sb, pat, remaining_a, remaining_b)

    return None

def main(input_str):
    lines = input_str.strip().split('\n')
    m = int(lines[0])
    output = []

    for i in range(1, m + 1):
        if i >= len(lines):
            break
        a, b = map(int, lines[i].split())

        result = solve_one(a, b)
        if result is None:
            output.append("Impossible")
        else:
            sa, sb, _, _, _ = result
            output.append(f"{sa}:{sb}")

    output.append("")
    print('\n'.join(output[:-1]))
